const STORE='nmg-onemap-upgrade-v1';
let saved={};try{saved=JSON.parse(localStorage.getItem(STORE)||'{}')}catch{}
const layers=NMG_LAYERS.map(l=>({...l,id:l.id.replace('nmg:',''),name:l.name.replace('（演示点位）','').replace('（示意）',''),features:l.features.map(f=>({...f,layerId:l.id.replace('nmg:',''),layerName:l.name}))}));
