const state={route:'map',active:new Set(['primeFarmland','ecoRedline','miningRight']),opacity:{},region:'',keyword:'',selected:null,resultRows:null,resultLabel:'当前可见图层',page:0,showResults:false,tool:'',draw:null,drawPoints:[],drawGeometry:null,drawLayer:null,inspector:'',resource:null,scene:new URLSearchParams(location.search).get('scene')||'steward',base:'terrain',catalogTab:'all',grouping:'theme',searchLayers:'',role:saved.role==='admin'?'admin':'analyst',requests:Array.isArray(saved.requests)?saved.requests:[],tasks:Array.isArray(saved.tasks)?saved.tasks:[],bookmarks:Array.isArray(saved.bookmarks)?saved.bookmarks:[],logs:Array.isArray(saved.logs)?saved.logs:[],imports:[],operations:Array.isArray(saved.operations)?saved.operations:[],messages:[],compare:100};
