function resourceList(){const matching=layers.filter(l=>!state.searchLayers||l.name.includes(state.searchLayers));const title=state.grouping==='region'?(state.region||'内蒙古自治区'):state.grouping==='department'?'自然资源业务资料 · 部门归属待接入':'空间图层';return `<p class="note" style="margin:4px 9px 8px">${title} · ${matching.length} 项</p>`+matching.map(l=>`<button class="side-item ${state.resource===l.id?'active':''}" data-action="resource" data-id="${l.id}"><span class="layer-symbol" style="color:${layerColor(l.id)};margin-top:5px"></span><span><strong>${esc(l.name)}</strong><small>${filteredLayer(l).length} 个对象 · ${l.features[0]?.geometry.type==='Point'?'点':'空间要素'} · 示例数据</small></span><span class="arrow">›</span></button>`).join('')}
function panel(title,en,body,footer='',kind='detail'){if(innerWidth<681)$('#sidebar').classList.add('mobile-hidden');state.inspector=kind;$('#inspector').hidden=false;$('#inspector').innerHTML=`<div class="inspector-header"><span class="eyebrow">${en}</span><h2>${title}</h2><button class="close-button" data-action="close-panel" aria-label="关闭详情面板">${icon('close')}</button></div><div class="inspector-body">${body}</div>${footer?`<div class="inspector-footer">${footer}</div>`:''}`;}
function closePanel(){state.inspector='';$('#inspector').hidden=true;}
function showOverview(){const list=visibleFeatures();const rankings=layers.filter(l=>state.active.has(l.id)).map(l=>({name:l.name,count:filteredLayer(l).length,color:layerColor(l.id)})).sort((a,b)=>b.count-a.count);const max=Math.max(1,...rankings.map(l=>l.count));panel('区域资源概览','REGIONAL OVERVIEW',`<div class="metric-line"><strong>${list.length.toLocaleString()}</strong><small>个可见对象</small></div><div class="stat-pair"><div><strong>${state.active.size.toString().padStart(2,'0')}</strong><small>已叠加专题图层</small></div><div><strong>${state.region?'01':'12'}</strong><small>当前盟市范围</small></div></div><h3>${state.region||'内蒙古自治区'}</h3><p class="note" style="margin-top:0">按当前图层和行政区动态统计对象数量。</p>${rankings.map(l=>`<div class="distribution-row"><div><span>${l.name}</span><span>${l.count}</span></div><div class="bar"><i style="width:${l.count/max*100}%;background:${l.color}"></i></div></div>`).join('')}<div class="hint">在地图上选择一个对象，即可查看属性、定位关联资源或发起核查任务。</div><p class="note">以上为本地模拟对象数量，不代表自治区资源家底总量。</p>`,`<button class="secondary wide" data-action="show-results">${icon('layers')} 查看属性表</button>`,'overview')}
function showResource(id){const l=byId[id];if(!l)return;state.resource=id;state.selected=null;const types=[...new Set(l.features.map(f=>f.geometry.type))];panel(esc(l.name),'RESOURCE METADATA',`<span class="tag">空间图层</span> <span class="tag gray">模拟示例</span><dl class="properties"><div><dt>对象数量</dt><dd>${filteredLayer(l).length} / ${l.features.length}</dd></div><div><dt>空间范围</dt><dd>${state.region||'内蒙古自治区'}</dd></div><div><dt>几何类型</dt><dd>${types.join(' / ')}</dd></div><div><dt>来源</dt><dd>既有 demo / oneMap 运行数据</dd></div><div><dt>坐标处理</dt><dd>沿用已有近似转换经纬度</dd></div><div><dt>使用范围</dt><dd>本地原型演示</dd></div><div><dt>更新方式</dt><dd>示例数据，未接入生产服务</dd></div></dl><h3>地图显示</h3><label class="field">图层不透明度<input type="range" min="10" max="100" value="${(state.opacity[id]??.65)*100}" data-opacity="${id}" aria-label="图层不透明度"></label><button class="secondary wide" data-action="preview-resource" data-id="${id}">${icon('eye')} 预览并查看属性</button><p class="note">点数据保留点几何，不作为矿权或建设用地的真实边界。</p>`,`<button class="primary" style="flex:1" data-action="request-resource" data-id="${id}">申请示例数据</button><button class="secondary" data-action="toggle-resource" data-id="${id}">${state.active.has(id)?'移除图层':'叠加图层'}</button>`,'resource');if(state.route==='resources')renderSidebar();}
function selectFeature(f){if(!f)return;state.selected=f;updateAssistantContext();if(detailHighlight)map.removeLayer(detailHighlight);detailHighlight=L.geoJSON(geometryFeature(f),{interactive:false,style:{color:'#164d3b',weight:3,fillOpacity:.15},pointToLayer:(x,ll)=>L.circleMarker(ll,{radius:8,color:'#164d3b',weight:2,fillColor:'#fff',fillOpacity:.5})}).addTo(map);const p=f.properties,c=Spatial.center(f.geometry);panel(esc(f.name),'FEATURE INSPECTOR',`<span class="tag">${esc(f.layerName)}</span><dl class="properties"><div><dt>对象编号</dt><dd>${esc(f.id)}</dd></div><div><dt>所在区域</dt><dd>${esc(f.region)} / ${esc(f.county||'—')}</dd></div><div><dt>几何类型</dt><dd>${f.geometry.type==='Point'?'点位示例':f.geometry.type==='LineString'?'线状示例':'面状示例'}</dd></div><div><dt>登记面积</dt><dd>${f.area!=null?Number(f.area).toLocaleString()+' '+esc(f.unit):'未提供'}</dd></div><div><dt>数据年度</dt><dd>${esc(p.year||'未提供')}</dd></div><div><dt>业务状态</dt><dd>${esc(p.approval||'未提供')}</dd></div>${p.validUntil?`<div><dt>有效期至</dt><dd>${esc(p.validUntil)}</dd></div>`:''}<div><dt>示例责任单位</dt><dd>${esc(p.owner||'未提供')}</dd></div><div><dt>中心位置</dt><dd>${c[0].toFixed(5)}°, ${c[1].toFixed(5)}°</dd></div></dl>${p.control?`<h3>源数据中的业务说明</h3><p class="note">${esc(p.control)}</p>`:''}<div class="hint">${f.geometry.type==='Point'?'本对象仅为位置示例，登记面积是属性值，不由点几何计算。':'登记面积沿用示例属性，与几何量算结果可能不一致。'}</div>`,`<button class="primary" data-action="task-new">创建核查任务</button><button class="secondary" data-action="locate-selected">${icon('pin')} 定位</button>`,'feature');}
function locateFeature(f){if(!f)return;selectFeature(f);const b=Spatial.bbox(f.geometry);map.fitBounds([[b[1],b[0]],[b[3],b[2]]],{paddingTopLeft:[50,50],paddingBottomRight:[350,state.showResults?280:60],maxZoom:f.geometry.type==='Point'?10:11,animate:false});}
function resultData(){return state.resultRows===null?visibleFeatures():state.resultRows;}
function showResults(rows=null,label='当前可见图层'){state.resultRows=rows;state.resultLabel=label;state.page=0;state.showResults=true;renderResults();}
function renderResults(){const el=$('#results');el.hidden=!state.showResults;$('.map-workspace').classList.toggle('has-results',state.showResults);if(!state.showResults)return;const rows=resultData(),size=20,pages=Math.max(1,Math.ceil(rows.length/size));state.page=Math.min(state.page,pages-1);const slice=rows.slice(state.page*size,(state.page+1)*size);el.innerHTML=`<div class="results-header"><strong>属性与查询结果</strong><small>${esc(state.resultRows===null?(state.region?state.region+' · ':'')+'当前可见图层':state.resultLabel)} · ${rows.length} 项</small><div class="right"><button class="text-button" data-action="fit-results">范围定位</button><button class="text-button" data-action="export-csv">${icon('download')} 导出本页</button><button data-action="close-results" aria-label="关闭属性表">${icon('close')}</button></div></div><div class="results-table">${rows.length?`<table><thead><tr><th>对象编号</th><th>名称</th><th>图层</th><th>盟市 / 旗县</th><th>登记面积</th><th>状态</th><th>操作</th></tr></thead><tbody>${slice.map(f=>`<tr><td>${esc(f.id)}</td><td><button data-action="select-feature" data-id="${f.id}">${esc(f.name)}</button></td><td>${esc(f.layerName)}</td><td>${esc(f.region)} / ${esc(f.county||'—')}</td><td>${f.area!=null?Number(f.area).toLocaleString()+' '+esc(f.unit):'—'}</td><td>${esc(f.properties.approval||'—')}</td><td><button data-action="locate-feature" data-id="${f.id}">定位 ↗</button></td></tr>`).join('')}</tbody></table>`:'<div class="results-empty">没有匹配对象。请扩大范围、切换图层或调整查询条件。</div>'}</div><div class="results-footer"><span>地图与属性表联动 · 模拟数据，登记面积不作为测绘成果</span><span><button data-action="page-prev" ${state.page===0?'disabled':''}>上一页</button>${state.page+1} / ${pages}<button data-action="page-next" ${state.page===pages-1?'disabled':''}>下一页</button></span></div>`;}
function fitFeatures(rows){if(!rows.length){toast('当前没有可定位的对象');return}let b=[180,90,-180,-90];rows.forEach(f=>{const x=Spatial.bbox(f.geometry);b=[Math.min(b[0],x[0]),Math.min(b[1],x[1]),Math.max(b[2],x[2]),Math.max(b[3],x[3])]});map.fitBounds([[b[1],b[0]],[b[3],b[2]]],{paddingTopLeft:[40,100],paddingBottomRight:[state.inspector?330:70,state.showResults?280:80],maxZoom:10,animate:false});}
function search(query){query=query.trim();if(!query){state.resultRows=null;showResults();return}const city=NMG_GEO.cities.features.find(f=>query===f.properties.name||query===f.properties.name.replace(/市$|盟$/,''));if(city){selectRegion(city.properties.name);showResults(null,city.properties.name);toast('已定位至'+city.properties.name);return}const matches=allFeatures.filter(f=>(!state.region||f.region===state.region)&&[f.id,f.name,f.layerName,f.region,f.county].some(x=>String(x).includes(query)));matches.forEach(f=>state.active.add(f.layerId));refreshMap();renderSidebar();showResults(matches,'搜索：'+query);if(matches.length)fitFeatures(matches);}
function openTool(id){state.tool=id;renderSidebar();cancelDraw();if(id!=='compare')stopCompare();
 if(id==='query')panel('空间范围查询','SPATIAL QUERY',`<p>用一个范围，找到当前图层中与其相交的对象。</p><h3>选择范围方式</h3><button class="primary wide" data-action="draw-query">${icon('polygon')} 在地图上绘制多边形</button><button class="secondary wide" style="margin-top:8px" data-action="draw-box">${icon('box')} 两点框选范围</button><h3>参与查询的图层</h3><p class="note">当前 ${state.active.size} 个可见图层；可切换至“一张图”调整。</p><div class="hint">点击地图添加顶点，至少 3 点后点击“完成”。Esc 取消；重新绘制会清除上次范围。</div><p class="note">对示例点、线、面执行几何相交查询。结果仅表示空间关系，不构成合规审查结论。</p>`, '', 'tool');
 if(id==='buffer')panel('周边缓冲分析','BUFFER ANALYSIS',`<p>选择中心点与距离，查找当前图层内的周边对象。</p><label class="field">中心点来源<select id="buffer-source"><option value="map">在地图上选择</option>${state.selected?'<option value="selected">当前选中对象的中心</option>':''}</select></label><label class="field">缓冲距离（公里）<input id="buffer-distance" type="number" min="0.1" max="300" step="0.1" value="10"></label><button class="primary wide" data-action="buffer-start">${icon('circle')} 开始周边分析</button><p class="note">使用球面缓冲范围，以 96 段多边形近似。多边形或线与范围相交即进入结果；距离不作为精密测量成果。</p>`, '', 'tool');
 if(id==='measure')panel('地图量算','GEOGRAPHIC MEASUREMENT',`<p>沿路径选点测距离，或闭合多边形测面积。</p><div class="field"><button class="primary wide" data-action="draw-distance">${icon('measure')} 测量距离</button><button class="secondary wide" data-action="draw-area">${icon('polygon')} 测量面积</button></div><div id="measure-result" class="hint">绘制后在这里显示计算结果。</div><p class="note">距离使用球面大圆距离；面积采用球面近似。地图显示坐标沿用既有 demo 的近似转换结果。</p>`, '', 'tool');
 if(id==='coordinate')panel('坐标定位与转换','COORDINATE TOOLS',`<form id="coordinate-form"><label class="field">经度（-180° 至 180°）<input id="coord-lng" type="number" step="any" min="-180" max="180" value="111.67" required></label><label class="field">纬度（-85° 至 85°）<input id="coord-lat" type="number" step="any" min="-85" max="85" value="40.82" required></label><button class="primary wide" type="submit">转换并定位</button></form><div id="coordinate-result" class="hint">经纬度 → Web Mercator（EPSG:3857）</div><p class="note">此工具不进行 GCJ-02、CGCS2000 高精度转换，也不代替测绘转换参数。</p>`, '', 'tool');
 if(id==='compare'){panel('专题图层卷帘','LAYER COMPARISON',`<p>滑动分隔线，对照基础底图和当前专题图层。</p><div class="hint">左侧：自然地理底图<br>右侧：已叠加的业务专题</div><p class="note">这是同一时点的图层对照。当前未提供经过核验的多期影像，不能用于认定历史变化。</p><button class="secondary wide" data-action="compare-stop">结束卷帘</button>`,'','tool');state.compare=50;const bar=document.createElement('div');bar.id='compare-control';bar.className='compare-control';bar.innerHTML='<label for="compare-range"><span>基础底图</span><span>业务专题</span></label><input id="compare-range" type="range" min="0" max="100" value="50" aria-label="卷帘分隔位置">';$('.map-workspace').append(bar);updateClip();}
 if(id==='import')panel('导入空间范围','GEOJSON PREVIEW',`<p>在本机读取 GeoJSON，并叠加到当前地图。</p><label class="field">选择文件（最大 5 MB）<input class="file-input" id="geojson-file" type="file" accept=".json,.geojson,application/geo+json,application/json"></label><div class="hint">支持 Point、LineString、Polygon 及其 Multi 类型；坐标必须是经度、纬度顺序。最多 1,000 个对象。</div><div id="import-result"></div><p class="note">文件仅在浏览器中读取，不上传。导入图层用于预览，尚未进入资源编目与业务审批。</p>`,'','tool');
}
function cancelDraw(){state.draw=null;state.drawPoints=[];$('#drawing-hint').hidden=true;$('.map-workspace').classList.remove('drawing');map.doubleClickZoom.enable();$$('#map-tools button').forEach(b=>b.classList.remove('active'));}
function startDraw(mode){cancelDraw();state.drawGeometry=null;updateAssistantContext();if(geoHighlight){map.removeLayer(geoHighlight);geoHighlight=null}state.draw=mode;state.drawPoints=[];$('#drawing-hint').hidden=false;const prompts={box:'在地图上点击两个对角点',buffer:'在地图上点击缓冲中心',query:'点击地图添加顶点',area:'点击地图添加面积范围顶点',distance:'点击地图添加路径点'};$('#drawing-hint').innerHTML=`${prompts[mode]}${['query','area','distance'].includes(mode)?'<button data-action="finish-draw">完成绘制</button><button data-action="undo-draw">撤销一点</button>':''}<button data-action="cancel-draw">取消 / Esc</button>`;$('.map-workspace').classList.add('drawing');map.doubleClickZoom.disable();if(innerWidth<681)$('#inspector').hidden=true;toast(prompts[mode]);}
function drawPreview(){if(geoHighlight)map.removeLayer(geoHighlight);if(!state.drawPoints.length)return;geoHighlight=L.featureGroup();if(state.drawPoints.length>1)L.polyline(state.drawPoints.map(p=>[p[1],p[0]]),{color:'#194f3b',weight:2,dashArray:'5 4'}).addTo(geoHighlight);state.drawPoints.forEach(p=>L.circleMarker([p[1],p[0]],{radius:4,color:'#194f3b',fillColor:'#fff',fillOpacity:1,weight:2}).addTo(geoHighlight));geoHighlight.addTo(map);}
function showGeometry(g){if(geoHighlight)map.removeLayer(geoHighlight);geoHighlight=L.geoJSON(g,{style:{color:'#194f3b',weight:2,dashArray:'6 4',fillColor:'#649c76',fillOpacity:.13}}).addTo(map);state.drawGeometry=g;updateAssistantContext();}
function runGeometryQuery(g,label){showGeometry(g);const matches=visibleFeatures().filter(f=>Spatial.intersects(f.geometry,g));showResults(matches,label);toast(`空间查询完成，找到 ${matches.length} 个对象`);log(label+'，匹配 '+matches.length+' 个模拟对象');}
function finishDraw(){const mode=state.draw,pts=[...state.drawPoints];if(mode==='distance'&&pts.length<2||mode!=='distance'&&pts.length<3){toast(mode==='distance'?'至少需要 2 个点':'至少需要 3 个点');return}if(mode!=='distance'){
 const ring=[...pts,pts[0]];for(let i=0;i<ring.length-1;i++)for(let j=i+2;j<ring.length-1;j++){if(i===0&&j===ring.length-2)continue;const a={type:'LineString',coordinates:[ring[i],ring[i+1]]},b={type:'LineString',coordinates:[ring[j],ring[j+1]]};if(Spatial.intersects(a,b)){toast('范围发生自相交，请撤销顶点后重新绘制');return}}
 }
 cancelDraw();if(innerWidth<681&&state.inspector)$('#inspector').hidden=false;
 if(mode==='distance'){const d=pts.slice(1).reduce((s,p,i)=>s+Spatial.distance(pts[i],p),0);showGeometry({type:'LineString',coordinates:pts});const text=`距离 ${(d/1000).toFixed(3)} 公里（球面近似）`;if($('#measure-result'))$('#measure-result').textContent=text;toast(text);return}
 const g={type:'Polygon',coordinates:[[...pts,pts[0]]]};if(Spatial.area(g)<1){toast('范围面积过小，请重新绘制');return}if(mode==='area'){showGeometry(g);const text=`面积 ${(Spatial.area(g)/10000).toLocaleString('zh-CN',{maximumFractionDigits:2})} 公顷（球面近似）`;if($('#measure-result'))$('#measure-result').textContent=text;toast(text);}else runGeometryQuery(g,'绘制范围相交查询');
}
map.on('click',e=>{if(!state.draw)return;const p=[e.latlng.lng,e.latlng.lat];if(state.draw==='buffer'){const radius=state.bufferRadius;cancelDraw();if(state.inspector)$('#inspector').hidden=false;runGeometryQuery(Spatial.circle(p,radius*1000),'周边 '+radius+' 公里');return}state.drawPoints.push(p);if(state.draw==='box'&&state.drawPoints.length===2){const [a,b]=state.drawPoints;cancelDraw();if(state.inspector)$('#inspector').hidden=false;const g={type:'Polygon',coordinates:[[a,[b[0],a[1]],b,[a[0],b[1]],a]]};if(Spatial.area(g)<1){toast('选区过小，请重新框选');return}runGeometryQuery(g,'框选范围相交查询');}else drawPreview();});
map.on('mousemove',e=>{$('#coords').textContent=`经度 ${e.latlng.lng.toFixed(4)}°　纬度 ${e.latlng.lat.toFixed(4)}°`});
map.on('zoomend',()=>{if(map.getZoom()>=7){if(!map.hasLayer(counties))counties.addTo(map)}else if(map.hasLayer(counties))map.removeLayer(counties)});
function updateClip(){const svg=map.getPane('business').querySelector('svg');if(!svg)return;const offset=map.getContainer().getBoundingClientRect().left+map.getSize().x*state.compare/100-svg.getBoundingClientRect().left;svg.style.clipPath=state.compare<100?`inset(0 0 0 ${Math.max(0,offset)}px)`:'';}
map.on('move zoom resize',updateClip);
function stopCompare(){state.compare=100;$('#compare-control')?.remove();updateClip();}
function showScene(id){const s=scenarios.find(s=>s.id===id)||scenarios[0];state.scene=s.id;setLayers(s.layers);$('#map-title').textContent=s.name;$('#map-subtitle').textContent=s.description;panel(s.name,s.en,`<p>${s.description}</p><h3>办理路径</h3>${s.steps.map((x,i)=>`<div class="flow-step"><b>${i+1}</b><span>${x}</span><small>${i===0?'从地图开始':''}</small></div>`).join('')}<h3>业务图层</h3><div class="chip-row">${s.layers.map(id=>`<button class="chip" data-action="resource" data-id="${id}">${byId[id].name}</button>`).join('')}</div><div class="field"><button class="secondary wide" data-action="scene-query">在当前区域查看业务对象</button><button class="secondary wide" data-action="draw-query">绘制范围并查询</button></div><p class="note">对应功能清单 ${s.requirement}。当前实现地图查询与核查任务主流程；专业评估、审批及外部系统接口见需求说明书。</p>`,`<button class="primary wide" data-action="task-new">创建场景核查任务</button>`,'scene');}
function updateAssistantContext(){const node=$('#assistant-context');if(node)node.textContent=[state.region||'全自治区',state.active.size+' 个图层',state.selected?'选中：'+state.selected.name:'未选中对象',state.drawGeometry?'已有绘制范围':''].filter(Boolean).join(' · ');}
function showAI(){state.assistantOpen=true;const dock=$('#assistant-dock');dock.hidden=false;dock.innerHTML=`<div class="inspector-header"><span class="eyebrow">YOUR SPATIAL COPILOT</span><h2>一张图助手</h2><button class="close-button" data-action="close-assistant" aria-label="收起智能助手">${icon('close')}</button></div><div id="assistant-context" class="assistant-context"></div><div class="assistant-conversation"><div class="chat-message"><small>空间协同 · 本地规则演示</small>我会结合你当前的区域、图层、选中对象与绘制范围，帮助查询、分析和办理。</div><div class="assistant-suggestions"><button data-prompt="分析当前范围">分析当前范围</button><button data-prompt="分析选中对象周边10公里">周边 10 公里</button><button data-prompt="叠加生态保护红线">叠加生态红线</button><button data-prompt="创建核查任务">创建核查任务</button></div><div id="chat-messages">${chatHTML()}</div></div><form id="chat-form" class="chat-composer"><textarea id="chat-input" aria-label="输入地图查询问题" placeholder="查询、叠加图层、分析范围，或继续办理…"></textarea><div><button type="button" class="text-button" data-action="clear-chat">新会话</button><span>本地规则 · 不作专业结论</span><button class="primary" type="submit">执行 ↗</button></div></form>`;updateAssistantContext();$('#chat-input').value=state.assistantDraft||'';$('#assistant-trigger').setAttribute('aria-expanded','true');}
function closeAI(){state.assistantDraft=$('#chat-input')?.value||'';state.assistantOpen=false;$('#assistant-dock').hidden=true;$('#assistant-trigger').setAttribute('aria-expanded','false');}
function chatHTML(){return state.messages.map(m=>`<div class="chat-message ${m.role}"><small>${m.role==='user'?'我的问题':'处理结果'}</small>${esc(m.text).replace(/\n/g,'<br>')}</div>`).join('')}
function matchAssistantLayers(q){const names=[...layers].sort((a,b)=>b.name.length-a.name.length);let matched=names.filter(l=>q.includes(l.name)||q.includes(l.name.replace(/分布|图斑|样点|斑块/g,'')));if(!matched.length){const aliases={永久基本农田:['primeFarmland'],基本农田:['primeFarmland'],生态保护红线:['ecoRedline'],生态红线:['ecoRedline'],耕地:['primeFarmland'],矿业权:['miningRight','exploreRight'],采矿权:['miningRight'],地灾:['geoHazard'],林地:['forest'],草原:['grassland'],建设用地:['construction']};for(const [word,ids] of Object.entries(aliases))if(q.includes(word)){matched=ids.map(id=>byId[id]);break}}return matched;}
function ask(q){q=q.trim();if(!q)return;state.assistantDraft='';state.messages.push({role:'user',text:q});let response='',after=null;
 if(/违法|合规|新增|趋势|最新|同比|历史/.test(q)){response='当前模拟数据不足以认定违法、合规或年度变化。可以先叠加管控图层、查询范围，再创建核查任务。';}
 else if(/(?:创建|新建|发起).*(?:核查|任务)/.test(q)){response='已准备核查任务表单，带入当前对象、区域、图层和绘制范围。请填写核查说明并保存；我不会直接代替你办结任务。';after=()=>createTask();}
 else if(/申请.*(?:数据|资源|图层)|申请当前/.test(q)){const l=byId[(state.route==='resources'?state.resource:state.selected?.layerId)||state.resource];if(l){response='已打开“'+l.name+'”的申请表。请确认用途、区域和使用期限后提交。';after=()=>requestResource(l.id)}else response='请先在资源中心选择一个图层，或在地图选中一个对象，再说“申请当前图层”。';}
 else if(/(?:打开|进入|切换).*(?:场景|大管家|矿业|耕地|规划|要素)/.test(q)){const s=scenarios.find(s=>q.includes(s.name)||q.includes(({steward:'大管家',planning:'规划',farmland:'耕地',elements:'要素',mining:'矿业'})[s.id]));if(s){response='已切换到“'+s.name+'”并加载相关图层。你可以继续查询、绘制范围或登记核查任务。';after=()=>{state.scene=s.id;if(state.route!=='scenes')location.hash='scenes';else showScene(s.id)}}else response='可打开资源大管家、国土空间规划、耕地保护、要素保障或矿业权场景。';}
 else if(/(?:打开|开始|进行).*(?:量算|测量)|测量面积|测量距离/.test(q)){const area=/面积/.test(q);response='已准备'+(area?'面积':'距离')+'量算。在地图连续选点，使用顶部“完成绘制”获得结果。助手会暂时收起，让出绘图空间。';after=()=>{openTool('measure');startDraw(area?'area':'distance');closeAI()};}
 else if(/周边/.test(q)){const m=q.match(/(?:周边)?\s*(-?[\d.]+)\s*(公里|千米|米)/),r=m?Number(m[1])*(m[2]==='米'?.001:1):10;if(!state.selected)response='请先点击一个地图对象，或在属性表选择对象。我会以该对象中心查询周边；当前没有选中对象。';else if(!Number.isFinite(r)||r<.1||r>300)response='请输入 0.1 至 300 公里的周边距离。';else {const g=Spatial.circle(Spatial.center(state.selected.geometry),r*1000);runGeometryQuery(g,'助手：周边 '+r+' 公里');state.aiRows=resultData();response='以“'+state.selected.name+'”的几何中心为起点，在当前可见图层中找到 '+state.aiRows.length+' 个与 '+r+' 公里缓冲范围相交的对象。\n结果已上图，可继续创建核查任务。点位中心不代表法定地块边界。';}}
 else if(/分析当前范围|查询当前范围|查询选区|分析选区/.test(q)){const geometry=state.drawGeometry;if(!geometry||geometry.type!=='Polygon'){response='当前没有可查询的多边形范围。已准备范围查询工具，点击地图绘制后完成。你也可以选择图层再来问我。';after=()=>openTool('query')}else {runGeometryQuery(geometry,'助手：当前绘制范围');state.aiRows=resultData();response='当前绘制范围与 '+state.aiRows.length+' 个可见对象相交，结果已同步地图和属性表。\n这是空间关系查询，不构成合规判断。';}}
 else if(/^(?:请)?(?:叠加|加载|显示|隐藏|移除|关闭)/.test(q)){const matched=matchAssistantLayers(q);if(!matched.length)response='没有找到相应图层。可以说“叠加永久基本农田”或“隐藏生态保护红线”。';else{const remove=/隐藏|移除|关闭/.test(q);matched.forEach(l=>remove?state.active.delete(l.id):state.active.add(l.id));state.resultRows=null;refreshMap();renderSidebar();response='已'+(remove?'隐藏':'叠加')+'：'+matched.map(l=>l.name).join('、')+'。当前视图位置保持，可继续做范围或周边分析。';}}
 else if(/按盟市统计/.test(q)&&state.aiRows){const counts={};state.aiRows.forEach(f=>counts[f.region]=(counts[f.region]||0)+1);response=`基于上次查询的 ${state.aiRows.length} 个对象，按盟市统计：\n`+Object.entries(counts).map(([n,v])=>`${n}：${v} 个`).join('\n');showResults(state.aiRows,'助手：按盟市统计');}
 else {const matched=matchAssistantLayers(q);const region=NMG_GEO.centers.features.map(f=>f.properties.name).find(n=>q.includes(n)||q.includes(n.replace(/市$|盟$/,'')));const year=q.match(/(20\d{2})年/),status=['审批中','已备案','待报批','已登记','未审批'].find(s=>q.includes(s));const amount=q.match(/(?:超过|大于)\s*([\d.]+)\s*(亩|公顷|平方公里)/);const followup=/只看|继续|其中/.test(q)&&state.aiRows;
 if(!matched.length&&!followup){response='可以查询“呼和浩特市的永久基本农田”，也可以说“叠加生态保护红线”“分析当前范围”“分析选中对象周边10公里”“创建核查任务”或“申请当前图层”。';}
 else {let rows=followup?[...state.aiRows]:matched.flatMap(l=>l.features);const targetRegion=region||state.region;if(targetRegion)rows=rows.filter(f=>f.region===targetRegion);if(region){state.region=region;$('#region').value=region}if(year)rows=rows.filter(f=>Number(f.properties.year)===Number(year[1]));if(status==='未审批')rows=rows.filter(f=>['待报批','审批中','未审批'].includes(f.properties.approval));else if(status)rows=rows.filter(f=>f.properties.approval===status);if(amount){const threshold=Number(amount[1])*({'亩':1,'公顷':15,'平方公里':1500}[amount[2]]);rows=rows.filter(f=>f.area!=null&&Number(f.area)*({'亩':1,'公顷':15,'平方公里':1500,'平方米':.0015}[f.unit]||0)>threshold)}state.aiRows=rows;matched.forEach(l=>state.active.add(l.id));refreshMap();renderSidebar();showResults(rows,'助手查询');if(rows.length)fitFeatures(rows);response=`找到 ${rows.length} 个模拟对象。\n范围：${targetRegion||'全自治区'}；图层：${matched.length?matched.map(l=>l.name).join('、'):'沿用上次结果'}${year?'；年度：'+year[1]:''}${status?'；状态：'+status:''}${amount?'；登记面积大于 '+amount[1]+amount[2]:''}。\n结果已同步到地图与属性表，原有图层继续保留。${status==='未审批'?'“未审批”演示口径为待报批、审批中或未审批。':''}`;}}
 state.messages.push({role:'assistant',text:response});showAI();$('#chat-messages')?.lastElementChild?.scrollIntoView({block:'nearest'});after?.();}
function modal(title,body,footer=''){const m=$('#modal');m.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="close-button" data-action="modal-close" aria-label="关闭对话框">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!m.open)m.showModal();}
function requestResource(id){const l=byId[id];modal('申请示例数据',`<form id="request-form"><input type="hidden" name="layer" value="${id}"><p><strong>${esc(l.name)}</strong></p><label class="field">申请用途<textarea name="purpose" required minlength="4" maxlength="500" placeholder="请填写具体用途（至少 4 个字）"></textarea></label><label class="field">行政区范围<select name="region"><option value="">全自治区</option>${NMG_GEO.centers.features.map(f=>`<option ${f.properties.name===state.region?'selected':''}>${f.properties.name}</option>`).join('')}</select></label><label class="field">使用期限<select name="days"><option value="7">7 天</option><option value="30">30 天</option><option value="90">90 天</option></select></label><p class="note">本地演示流程。提交后需切换“演示管理员”审核，审核通过可下载所选区域的示例 GeoJSON。</p></form>`,`<button class="secondary" data-action="modal-close">取消</button><button class="primary" type="submit" form="request-form">提交申请</button>`);}
function showRequests(admin=false){const pending=state.requests.filter(r=>r.status==='待审核').length;panel(admin?'使用申请审核':'我的资源申请',admin?'REQUEST REVIEW':'MY REQUESTS',`<div class="metric-line"><strong>${admin?pending:state.requests.length}</strong><small>${admin?'项待审核':'项申请记录'}</small></div>${admin&&state.role!=='admin'?'<div class="hint warning">当前为业务人员视图。切换为演示管理员后可执行本地审核。</div><button class="secondary wide" data-action="identity">切换演示身份</button>':''}${state.requests.length?state.requests.slice().reverse().map(r=>{const expired=r.status==='已通过'&&Date.now()>r.expires;return `<div class="link-row"><div><strong class="object-title">${esc(r.resourceName||byId[r.layer]?.name||r.layer)}</strong><small style="display:block;margin:4px 0">${esc(r.region||'全自治区')} · ${r.days} 天</small><span class="tag ${r.status==='待审核'?'amber':''}">${expired?'已到期':r.status}</span></div><button data-action="request-detail" data-id="${r.id}" data-admin="${admin}">查看 ›</button></div>`}).join(''):'<p class="empty-text">还没有申请。<br>前往资源中心选择图层后发起。</p>'}`,'','requests');}
function requestDetail(id,admin=false){const r=state.requests.find(x=>x.id===id);if(!r)return;const expired=r.status==='已通过'&&Date.now()>r.expires;modal('资源申请详情',`<dl class="properties"><div><dt>申请编号</dt><dd>${esc(r.id)}</dd></div><div><dt>数据资源</dt><dd>${esc(byId[r.layer].name)}</dd></div><div><dt>申请范围</dt><dd>${esc(r.region||'全自治区')}</dd></div><div><dt>申请用途</dt><dd>${esc(r.purpose)}</dd></div><div><dt>状态</dt><dd>${expired?'已到期':r.status}</dd></div><div><dt>申请时间</dt><dd>${esc(r.time)}</dd></div>${r.review?`<div><dt>审核意见</dt><dd>${esc(r.review)}</dd></div>`:''}${r.expires?`<div><dt>有效期至</dt><dd>${new Date(r.expires).toLocaleString('zh-CN')}</dd></div>`:''}</dl>${admin&&r.status==='待审核'&&state.role==='admin'?'<label class="field">审核意见（退回必填）<textarea id="review-comment" placeholder="请输入处理意见"></textarea></label>':''}`,admin&&r.status==='待审核'&&state.role==='admin'?`<button class="danger" data-action="reject-request" data-id="${id}">退回</button><button class="primary" data-action="approve-request" data-id="${id}">审核通过</button>`:r.status==='已通过'&&!expired?`<button class="primary" data-action="download-resource" data-id="${id}">下载示例 GeoJSON</button>`:r.status==='待审核'?`<button class="secondary" data-action="withdraw-request" data-id="${id}">撤回申请</button>`:'');}
function createTask(){const scene=scenarios.find(s=>s.id===state.scene);modal('创建空间核查任务',`<form id="task-form"><label class="field">任务名称<input name="title" required minlength="3" maxlength="80" value="${esc(state.selected?state.selected.name+'核查':scene.name+'范围核查')}"></label><label class="field">责任单位<input name="owner" required value="${esc(state.selected?.properties.owner||'自治区自然资源业务部门（演示）')}"></label><label class="field">核查说明<textarea name="description" required minlength="4" maxlength="1000" placeholder="说明需要核查的空间问题与处理要求"></textarea></label><div class="hint">关联对象：${esc(state.selected?.name||'当前地图范围')}<br>关联场景：${scene.name}<br>将保存当前区域、图层与视图，便于继续办理。</div></form>`,`<button class="secondary" data-action="modal-close">取消</button><button class="primary" type="submit" form="task-form">保存核查任务</button>`);}
function showTasks(){panel('空间核查任务','SPATIAL TASKS',`<div class="metric-line"><strong>${state.tasks.filter(t=>t.status!=='已办结').length}</strong><small>项待处理</small></div>${state.tasks.length?state.tasks.slice().reverse().map(t=>`<div class="link-row"><div><strong class="object-title">${esc(t.title)}</strong><small style="display:block">${esc(t.owner)}</small><span class="tag ${t.status==='待核查'?'amber':''}">${t.status}</span></div><button data-action="task-detail" data-id="${t.id}">办理 ›</button></div>`).join(''):'<p class="empty-text">还没有核查任务。<br>在地图选择对象，或进入业务场景创建。</p>'}`,`<button class="primary wide" data-action="task-new">新建核查任务</button>`,'tasks');}
function taskDetail(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;state.currentTask=id;restoreView(t.view);if(t.geometry)showGeometry(t.geometry);if(t.feature){const f=allFeatures.find(f=>f.id===t.feature);if(f){state.selected=f;locateFeature(f)}}panel(esc(t.title),'TASK DETAIL',`<span class="tag">${t.status}</span><dl class="properties"><div><dt>任务编号</dt><dd>${esc(t.id)}</dd></div><div><dt>责任单位</dt><dd>${esc(t.owner)}</dd></div><div><dt>创建时间</dt><dd>${esc(t.time)}</dd></div><div><dt>核查说明</dt><dd>${esc(t.description)}</dd></div></dl><h3>办理记录</h3><ol class="timeline">${t.history.map(h=>`<li class="active">${esc(h.action)}<small>${esc(h.time)}${h.note?'<br>'+esc(h.note):''}</small></li>`).join('')}</ol>${t.status!=='已办结'?'<label class="field">处理意见<textarea id="task-note" placeholder="填写核查处理情况"></textarea></label>':''}`,t.status==='待核查'?`<button class="primary wide" data-action="task-progress" data-id="${id}">领取并开始核查</button>`:t.status==='核查中'?`<button class="primary wide" data-action="task-progress" data-id="${id}">记录结果并办结</button>`:`<button class="secondary wide" data-action="tasks">返回任务列表</button>`,'task');}
function captureView(){return {center:[map.getCenter().lat,map.getCenter().lng],zoom:map.getZoom(),layers:[...state.active],region:state.region,base:state.base};}
function restoreView(v){if(!v)return;state.active=new Set((v.layers||[]).filter(id=>byId[id]));state.region=v.region||'';$('#region').value=state.region;setBase(v.base||'terrain');refreshMap();renderSidebar();map.setView(v.center,v.zoom,{animate:false});}
function saveBookmark(){modal('保存当前地图视图',`<form id="bookmark-form"><label class="field">书签名称<input name="name" required minlength="2" maxlength="60" value="${esc(state.region||'内蒙古')}${state.route==='scenes'?' · '+scenarios.find(s=>s.id===state.scene).name:' · 专题视图'}"></label><p class="note">保存当前中心位置、缩放层级、行政区、底图和已选图层。</p></form>`,`<button class="primary" type="submit" form="bookmark-form">保存书签</button>`);}
function showBookmarks(){modal('视图与场景书签',`<div class="bookmarks-list">${state.bookmarks.length?state.bookmarks.map(b=>`<div class="link-row"><button data-action="restore-bookmark" data-id="${b.id}">${esc(b.name)}<small style="display:block">${b.view.layers.length} 个图层 · ${esc(b.view.region||'全自治区')}</small></button><button data-action="delete-bookmark" data-id="${b.id}" aria-label="删除书签 ${esc(b.name)}">${icon('trash')}</button></div>`).join(''):'<p class="empty-text">尚未保存视图。<br>将当前专题组合保存后可一键恢复。</p>'}</div>`,`<button class="primary" data-action="save-bookmark">保存当前视图</button>`);}
function showOperations(){panel('归集与发布','DATA PIPELINE',`<p>按阶段查看数据准备情况，把问题定位到地图。</p><div class="step-strip"><span class="done">登记</span> › <span>质检</span> › <span>编目</span> › <span>发布</span></div>${state.operations.length?state.operations.map(o=>`<div class="link-row"><div><strong class="object-title">${esc(o.name)}</strong><small style="display:block">${esc(byId[o.layer]?.name||o.layer)}</small><span class="tag">${o.status}</span></div><button data-action="operation-detail" data-id="${o.id}">处理 ›</button></div>`).join(''):'<p class="empty-text">还没有归集登记。<br>选择一个现有示例图层开始流程。</p>'}<p class="note">质检对当前示例对象检查名称、坐标范围与几何基本结构；发布登记保存在本地，不生成外部 OGC 服务。</p>`,`<button class="primary wide" data-action="operation-new">新建归集登记</button>`,'operations');}
function operationNew(){modal('新建归集登记',`<form id="operation-form"><label class="field">登记名称<input name="name" required minlength="3" maxlength="80" placeholder="例如：呼和浩特耕地专题更新"></label><label class="field">数据来源<select name="layer">${layers.map(l=>`<option value="${l.id}">${esc(l.name)} · 现有示例</option>`).join('')}</select></label><label class="field">数源单位<input name="owner" required placeholder="请输入演示数源单位"></label><p class="note">本轮使用已有本地示例数据演示归集流程，不连接生产库。</p></form>`,`<button class="primary" type="submit" form="operation-form">建立登记</button>`);}
function operationDetail(id){const o=state.operations.find(x=>x.id===id);if(!o)return;state.currentOperation=id;state.active.add(o.layer);refreshMap();renderSidebar();panel(esc(o.name),'PIPELINE DETAIL',`<span class="tag">${o.status}</span><dl class="properties"><div><dt>数源单位</dt><dd>${esc(o.owner)}</dd></div><div><dt>关联图层</dt><dd>${esc(byId[o.layer].name)}</dd></div><div><dt>登记时间</dt><dd>${esc(o.time)}</dd></div><div><dt>对象数量</dt><dd>${byId[o.layer].features.length}</dd></div></dl>${o.check?`<h3>基础质检结果</h3><div class="hint ${o.check.errors?'warning':''}">检查 ${o.check.total} 个对象<br>发现 ${o.check.errors} 项基础问题</div><p class="note">检查内容：名称非空、经纬度范围、线最少点数、面环闭合。未包含专业拓扑与业务规则质检。</p>`:''}${o.status==='待编目'?`<label class="field">资源中文名称<input id="catalog-name" value="${esc(o.catalogName||o.name)}" maxlength="80"></label><label class="field">主题分类<select id="catalog-theme">${groups.map(g=>`<option>${g[0]}</option>`).join('')}</select></label>`:''}${o.catalogName?`<h3>编目信息</h3><p>${esc(o.catalogName)}<br><small>${esc(o.theme)}</small></p>`:''}${o.status==='已发布'?'<div class="hint">已完成本地发布登记，可返回资源目录预览图层。</div>':''}`,`<button class="primary wide" data-action="operation-next" data-id="${id}" ${o.status==='已发布'?'disabled':''}>${({'待质检':'执行基础质检','质检未通过':'重新质检','待编目':'保存编目信息','待发布':'发布至本地演示目录','已发布':'已完成本地发布'})[o.status]}</button>`,'operation');}
function geometryError(g){if(!g||!Array.isArray(g.coordinates))return true;if(g.type==='MultiLineString'&&g.coordinates.some(r=>!Array.isArray(r)||r.length<2))return true;const p=Spatial.points(g);if(!p.length||p.some(p=>!Array.isArray(p)||!Number.isFinite(p[0])||!Number.isFinite(p[1])||Math.abs(p[0])>180||Math.abs(p[1])>90))return true;if(g.type==='LineString'&&p.length<2)return true;const polys=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];return polys.some(poly=>!poly.length||poly.some(r=>r.length<4||r[0][0]!==r.at(-1)[0]||r[0][1]!==r.at(-1)[1]));}
function showIdentity(){modal('演示身份与使用说明',`<p>当前身份：<strong>${state.role==='admin'?'演示管理员':'业务人员'}</strong></p><div class="field"><button class="secondary" data-action="role-analyst">以业务人员查看</button><button class="secondary" data-action="role-admin">以演示管理员查看</button></div><p class="note">身份切换仅用于展示交互和本地审核流程，不属于真实登录、角色鉴权或单点登录。业务记录保存在当前浏览器，不在不同设备间同步。</p><div class="hint">本地行政区与业务数据复用已有 demo；业务要素为模拟示例。真实数据、法定边界、统一用户中心与生产业务接口尚未接入。</div><h3>完整业务模块</h3><p class="note">以下入口沿用原 oneMap，需要通过项目自带服务运行。</p><div class="field"><a class="secondary" href="../index.html#/admin/overview">打开完整后台管理 ↗</a><a class="secondary" href="../index.html#/front/app-center">打开应用构建中心 ↗</a><a class="secondary" href="../index.html#/front/intelligence">打开原智能中心 ↗</a></div>`);}
function showIntegrations(monitor=false){const names=['测绘地理信息时空大数据服务平台','全区不动产登记信息管理平台','地质灾害防治平台','地质调查监测管理系统','国土空间规划“一张图”实施监督信息系统','土地资源信息储备系统','耕地保护与监测监管信息系统','多级一体化电子政务平台','自然资源厅门户网站'];panel(monitor?'系统接入与监测说明':'已有系统集成','SYSTEM INTEGRATION',`<p class="note" style="margin-top:0">可研列出的接入系统。当前未配置经过确认的访问地址与认证接口。</p>${names.map((n,i)=>`<div class="link-row"><span>${n}<small style="display:block">${i===8?'访问入口':i===4||i===6?'入口 + 单点登录 + 待办':'入口 + 单点登录'}</small></span><span class="tag gray">待接入</span></div>`).join('')}<p class="note">国家节点与三级租户贯通、实时服务巡检、主机/数据库监控属于后续对接范围。当前不展示虚构的在线率或接口健康值。</p>`,'','integrations');}
