document.addEventListener('input',e=>{if(e.target.id==='layer-search'){state.searchLayers=e.target.value;$('#layer-tree').innerHTML=treeHTML()}if(e.target.id==='resource-search'){state.searchLayers=e.target.value;$('#resource-list').innerHTML=resourceList()}if(e.target.dataset.opacity){state.opacity[e.target.dataset.opacity]=Number(e.target.value)/100;refreshMap()}if(e.target.id==='compare-range'){state.compare=Number(e.target.value);updateClip()}});
document.addEventListener('change',async e=>{if(e.target.dataset.layer)toggleLayer(e.target.dataset.layer);if(e.target.id==='region')selectRegion(e.target.value);if(e.target.id==='geojson-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('文件大于 5 MB');const parsed=JSON.parse(await file.text());const fc=parsed.type==='FeatureCollection'?parsed:parsed.type==='Feature'?{type:'FeatureCollection',features:[parsed]}:{type:'FeatureCollection',features:[{type:'Feature',geometry:parsed,properties:{}}]};if(!Array.isArray(fc.features)||fc.features.length===0||fc.features.length>1000)throw new Error('需要 1 至 1,000 个对象');for(const f of fc.features){if(!['Point','MultiPoint','LineString','MultiLineString','Polygon','MultiPolygon'].includes(f.geometry?.type)||geometryError(f.geometry))throw new Error('几何结构或经纬度范围不正确')}const layer=L.geoJSON(fc,{style:{color:'#8059a0',weight:2,fillOpacity:.2},pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:6,color:'#8059a0'})}).addTo(map);state.imports.push(layer);map.fitBounds(layer.getBounds(),{padding:[60,60],maxZoom:12});$('#import-result').innerHTML=`<div class="hint">已预览 ${fc.features.length} 个对象<br>${esc(file.name)}</div>`;}catch(error){$('#import-result').innerHTML=`<div class="hint warning">导入失败：${esc(error.message)}。请检查文件后重试。</div>`}}});
